// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive     = errors.New("the plan is not active")
	ErrCanceled         = errors.New("the subscription is canceled")
	ErrIncompatiblePlan = errors.New("the plans differ in currency or interval, or one of them is metered")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The subscription's value is its plan's unit amount times its quantity,
// and the change is judged against the value in effect now:
//
//   - An upgrade (the value rises) applies at once and is billed at once: an invoice for the rest of the current period,
//     credited with the unused time on the old plan and charged with the remaining time on the new one. The current period
//     does not change.
//   - A downgrade (the value falls) does not apply now. It is held as the pending plan and quantity and takes effect at the
//     next renewal, which bills it. Another change replaces a pending one.
//   - A change that keeps the value equal applies at once and bills nothing.
//
// Any change that applies now clears a pending change. A trialing subscription's change applies at once and bills nothing.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	before, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	from, ok := s.Store.Plan(orgID, before.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	to := from
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
		to = p
	}
	quantity := before.Quantity
	if in.Quantity != nil {
		quantity = *in.Quantity
	}
	if quantity < 1 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	if !compatible(from, to) {
		return store.Subscription{}, ErrIncompatiblePlan
	}

	now := s.Clock.Now()
	// Set inside the update, which holds the store's lock: what the change bills, if it is an upgrade.
	var lines []store.Line
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		// The change was worked out from the plan and quantity read above; another change in between would make it wrong.
		if sub.PlanID != from.ID || sub.Quantity != before.Quantity {
			return fmt.Errorf("%w: the subscription changed; try again", store.ErrConflict)
		}
		oldValue := from.UnitAmount * int64(sub.Quantity)
		newValue := to.UnitAmount * int64(quantity)
		if sub.Status != store.Trialing && newValue < oldValue {
			pid, pq := to.ID, quantity
			sub.PendingPlanID, sub.PendingQuantity = &pid, &pq
			return nil
		}
		sub.PlanID, sub.Quantity = to.ID, quantity
		sub.PendingPlanID, sub.PendingQuantity = nil, nil
		if sub.Status != store.Trialing && newValue > oldValue {
			remaining, length := remainingSpan(*sub, now)
			lines = prorationLines(from, to, oldValue, newValue, remaining, length)
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if lines == nil {
		return sub, nil
	}
	paid, err := s.bill(ctx, sub, to.Currency, lines, now, sub.CurrentPeriodEnd)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

// compatible reports whether a subscription may change from plan a to plan b: they must bill in the same currency and
// interval, and neither may be metered.
func compatible(a, b store.Plan) bool {
	return a.Currency == b.Currency && a.Interval == b.Interval && a.UsageType == store.Licensed && b.UsageType == store.Licensed
}

// remainingSpan returns the time from now to the end of the subscription's current period and the length of that period.
// The remaining time is clamped to the period. Both are exact durations; only their ratio is used, so it is the same as the
// ratio in seconds.
func remainingSpan(sub store.Subscription, now time.Time) (remaining, length time.Duration) {
	length = sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart)
	remaining = min(max(sub.CurrentPeriodEnd.Sub(now), 0), length)
	return remaining, length
}

// prorationLines are the two lines of an upgrade's invoice: the unused time on the old plan (a credit) and the remaining
// time on the new one. Each amount is rounded to a whole minor unit.
func prorationLines(from, to store.Plan, fromValue, toValue int64, remaining, length time.Duration) []store.Line {
	return []store.Line{
		{Description: "Unused time on " + from.Name, Quantity: 1, UnitAmount: -billing.Prorate(fromValue, int64(remaining), int64(length))},
		{Description: "Remaining time on " + to.Name, Quantity: 1, UnitAmount: billing.Prorate(toValue, int64(remaining), int64(length))},
	}
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, on the pending plan and quantity if a downgrade is pending; a metered plan bills the usage of the
// period that ended. A declined charge makes the subscription past due. RenewDue returns how many subscriptions it renewed
// or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	// A pending downgrade takes effect now: the new period is billed on the pending plan and quantity.
	pending := sub.PendingPlanID != nil && sub.PendingQuantity != nil
	if pending {
		if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
			return store.ErrNotFound
		}
		sub.PlanID, sub.Quantity = plan.ID, *sub.PendingQuantity
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if pending {
			x.PlanID, x.Quantity = sub.PlanID, sub.Quantity
			x.PendingPlanID, x.PendingQuantity = nil, nil
		}
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	return s.bill(ctx, sub, plan.Currency, lines, start, end)
}

// bill creates an open invoice for a subscription's period with these lines and charges it to the customer's default
// payment method. It reports false when the charge was declined; see invoicePeriod for the rest.
func (s *Service) bill(ctx context.Context, sub store.Subscription, currency money.Currency, lines []store.Line, start, end time.Time) (bool, error) {
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}

