package subscriptions_test

import (
	"context"
	"errors"
	"slices"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// setup returns a service with a customer of Acme who has a card on file.
func setup(t *testing.T) (*apitest.Env, store.Customer) {
	t.Helper()
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	return e, c
}

// subscriptionInvoices returns the invoices of a subscription, oldest first.
func subscriptionInvoices(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

// The tests below use a monthly period from apitest.Start (January 15, 2026) to February 15, 2026: 31 days. Ten days in,
// 21 of the 31 days remain.
const tenDays = 10 * 24 * time.Hour

func TestUpgradeBillsTheRestOfThePeriod(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &business.ID})
	if err != nil {
		t.Fatal(err)
	}
	if sub.PlanID != business.ID || sub.Quantity != 1 || sub.Status != store.Active || sub.PendingPlanID != nil || sub.PendingQuantity != nil {
		t.Fatalf("subscription = %+v", sub)
	}
	if !sub.CurrentPeriodStart.Equal(apitest.Start) || !sub.CurrentPeriodEnd.Equal(apitest.Start.AddDate(0, 1, 0)) {
		t.Fatalf("the period changed: %v to %v", sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	}
	invs := subscriptionInvoices(e, sub)
	if len(invs) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	up := invs[1]
	// 21/31 of 2000 is 1354.84 (1355); 21/31 of 5000 is 3387.10 (3387).
	want := []store.Line{{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}, {Description: "Remaining time on Business", Quantity: 1, UnitAmount: 3387}}
	if !slices.Equal(up.Lines, want) || up.Status != store.InvoicePaid {
		t.Fatalf("upgrade invoice = %+v", up)
	}
	if got := billing.Compute(up).Total; got != 2032 {
		t.Fatalf("upgrade total = %d", got)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeAppliesTheDiscountAndTax(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	if _, err := e.Store.UpdateOrg(e.Acme.ID, func(o *store.Org) error { o.TaxRateBP = 2000; return nil }); err != nil {
		t.Fatal(err)
	}
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1, DiscountPercent: 10})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &business.ID}); err != nil {
		t.Fatal(err)
	}
	invs := subscriptionInvoices(e, sub)
	// Subtotal 2032; 10% off is 203.2 (203); the tax is 20% of 1829, 365.8 (366).
	if got := billing.Compute(invs[1]); got != (billing.Totals{Subtotal: 2032, Discount: 203, Tax: 366, Total: 2195}) {
		t.Fatalf("totals = %+v", got)
	}
	if cs := e.Gateway.Charges(); cs[len(cs)-1].Amount != 2195 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "John", "john@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &business.ID})
	if err != nil {
		t.Fatal(err)
	}
	invs := subscriptionInvoices(e, sub)
	if sub.Status != store.Active || sub.PlanID != business.ID || len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("subscription = %+v, invoices = %+v", sub, invs)
	}
	if n := len(e.Gateway.Calls()); n != 0 {
		t.Fatalf("%d charge attempts without a payment method", n)
	}
}

func TestDeclinedUpgradeAppliesButIsPastDue(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	e.Clock.Advance(tenDays)
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &business.ID})
	if err != nil {
		t.Fatal(err)
	}
	if sub.Status != store.PastDue || sub.PlanID != business.ID {
		t.Fatalf("subscription = %+v", sub)
	}
	invs := subscriptionInvoices(e, sub)
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v", invs)
	}
	if ps := e.Store.Payments(e.Acme.ID, invs[1].ID); len(ps) != 1 || ps[0].Status != store.PaymentFailed {
		t.Fatalf("payments = %+v", ps)
	}
}

func TestDowngradeTakesEffectAtRenewal(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: business.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID})
	if err != nil {
		t.Fatal(err)
	}
	if sub.PlanID != business.ID || sub.Quantity != 2 || sub.PendingPlanID == nil || *sub.PendingPlanID != team.ID ||
		sub.PendingQuantity == nil || *sub.PendingQuantity != 2 {
		t.Fatalf("subscription = %+v", sub)
	}
	if n := len(subscriptionInvoices(e, sub)); n != 1 || len(e.Gateway.Charges()) != 1 {
		t.Fatalf("a downgrade was billed: %d invoices, %d charges", n, len(e.Gateway.Charges()))
	}

	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.PlanID != team.ID || got.Quantity != 2 || got.PendingPlanID != nil || got.PendingQuantity != nil || got.Status != store.Active {
		t.Fatalf("after renewal = %+v", got)
	}
	invs := subscriptionInvoices(e, sub)
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 2 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
}

func TestPendingDowngradeIsReplacedOrCleared(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	business := e.CreatePlan(e.Acme, "Business", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: business.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	update := func(in subscriptions.UpdateInput) store.Subscription {
		t.Helper()
		sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, in)
		if err != nil {
			t.Fatal(err)
		}
		return sub
	}

	// A smaller quantity is a downgrade: pending, with the current plan.
	one := 1
	update(subscriptions.UpdateInput{Quantity: &one})
	if sub.PendingPlanID == nil || *sub.PendingPlanID != business.ID || sub.PendingQuantity == nil || *sub.PendingQuantity != 1 || sub.Quantity != 2 {
		t.Fatalf("pending = %+v", sub)
	}
	// Back to the current plan and quantity clears it, and bills nothing.
	two := 2
	update(subscriptions.UpdateInput{PlanID: &business.ID, Quantity: &two})
	if sub.PendingPlanID != nil || sub.PendingQuantity != nil || len(subscriptionInvoices(e, sub)) != 1 {
		t.Fatalf("pending was not cleared: %+v", sub)
	}
	// A lower-priced plan is pending again...
	update(subscriptions.UpdateInput{PlanID: &team.ID})
	if sub.PendingPlanID == nil || *sub.PendingPlanID != team.ID {
		t.Fatalf("pending = %+v", sub)
	}
	// ...and an upgrade applies at once, clearing it.
	three := 3
	update(subscriptions.UpdateInput{Quantity: &three})
	if sub.PlanID != business.ID || sub.Quantity != 3 || sub.PendingPlanID != nil || sub.PendingQuantity != nil {
		t.Fatalf("after an upgrade = %+v", sub)
	}
	if n := len(subscriptionInvoices(e, sub)); n != 2 {
		t.Fatalf("invoices = %d, want the first and the upgrade", n)
	}
}

func TestEqualValueChangeAppliesWithoutBilling(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	cheap := e.CreatePlan(e.Acme, "Cheap", "USD", "10.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(tenDays)
	four := 4
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &cheap.ID, Quantity: &four})
	if err != nil {
		t.Fatal(err)
	}
	// Both are 4000 a period.
	if sub.PlanID != cheap.ID || sub.Quantity != 4 || sub.PendingPlanID != nil {
		t.Fatalf("subscription = %+v", sub)
	}
	if n := len(subscriptionInvoices(e, sub)); n != 1 || len(e.Gateway.Charges()) != 1 {
		t.Fatalf("an equal change was billed")
	}
}

func TestTrialingChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	trial, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Trial", Currency: money.USD, UnitAmount: 5000, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: trial.ID, Quantity: 1})
	if err != nil || sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v, %v", sub, err)
	}
	e.Clock.Advance(3 * 24 * time.Hour)
	// A downgrade in value, but a trial's change applies at once.
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID})
	if err != nil {
		t.Fatal(err)
	}
	if sub.PlanID != team.ID || sub.PendingPlanID != nil || sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	five := 5
	sub, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &five})
	if err != nil {
		t.Fatal(err)
	}
	if sub.Quantity != 5 || sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	if n := len(e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{})); n != 0 {
		t.Fatalf("a trial's change was invoiced: %d invoices", n)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	now := e.Clock.Now()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	eur, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "EU", Currency: money.EUR, UnitAmount: 2000, Interval: store.Monthly}, now)
	yearly, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 20000, Interval: store.Yearly}, now)
	metered, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, now)
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, p := range []store.Plan{eur, yearly, metered} {
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &p.ID}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: %v", p.Name, err)
		}
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}

	ms, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: metered.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	two := 2
	if _, err := e.Subs.Update(ctx, e.Acme.ID, ms.ID, subscriptions.UpdateInput{Quantity: &two}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("metered quantity change: %v", err)
	}
}

func TestCanceledSubscriptionCannotChange(t *testing.T) {
	e, c := setup(t)
	ctx := context.Background()
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.Cancel(ctx, e.Acme.ID, sub.ID, false); err != nil {
		t.Fatal(err)
	}
	two := 2
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{Quantity: &two}); !errors.Is(err, subscriptions.ErrCanceled) {
		t.Fatalf("update a canceled subscription: %v", err)
	}
}

